var longestSubarray = function(nums, k) {
    let freq = new Map();
    let left = 0, repeated = 0, ans = 0;

    for (let right = 0; right < nums.length; right++) {
        freq.set(nums[right], (freq.get(nums[right]) || 0) + 1);

        if (freq.get(nums[right]) === 2)
            repeated++;

        while (repeated > k) {
            freq.set(nums[left], freq.get(nums[left]) - 1);

            if (freq.get(nums[left]) === 1)
                repeated--;

            left++;
        }

        ans = Math.max(ans, right - left + 1);
    }

    return ans;
};

var earliestFinishTime = function(landStart, landDur, waterStart, waterDur) {
    let ans = Infinity;

    for (let i = 0; i < landStart.length; i++) {
        let landEnd = landStart[i] + landDur[i];

        for (let j = 0; j < waterStart.length; j++) {
            let start = Math.max(landEnd, waterStart[j]);
            ans = Math.min(ans, start + waterDur[j]);
        }
    }

    return ans;
};

var maxWeight = function(weights) {
    weights.sort((a, b) => b - a);

    let n = weights.length;
    let bag1 = 0, bag2 = 0;

    for (let i = 0; i < n / 2; i++)
        bag1 += weights[i];

    for (let i = Math.floor(n / 2); i < n; i++)
        bag2 += weights[i];

    return Math.abs(bag1 - bag2);
};

var maxBalancedShipments = function(weight) {
    let ans = 0;
    let mn = weight[0];

    for (let i = 1; i < weight.length; i++) {
        if (weight[i] > mn) {
            ans++;
            mn = Infinity;
        } else {
            mn = Math.min(mn, weight[i]);
        }
    }

    return ans;
};

var trionic = function(nums) {
    let n = nums.length;
    let inc = new Array(n).fill(1);
    let dec = new Array(n).fill(1);

    for (let i = 1; i < n; i++) {
        if (nums[i] > nums[i - 1])
            inc[i] = inc[i - 1] + 1;
    }

    for (let i = n - 2; i >= 0; i--) {
        if (nums[i] > nums[i + 1])
            dec[i] = dec[i + 1] + 1;
    }

    let ans = 0;

    for (let i = 0; i < n; i++)
        ans = Math.max(ans, inc[i] + dec[i] - 1);

    return ans;
};

var nextPalindrome = function(n) {
    n++;

    while (true) {
        let s = n.toString();

        if (s === s.split('').reverse().join(''))
            return n;

        n++;
    }
};

var sortThreats = function(threats) {
    threats.sort((a, b) => {
        if (a[0] !== b[0])
            return b[0] - a[0];

        return b[1] - a[1];
    });

    return threats;
};
